// ─────────────────────────────────────────────────────────────────
//  PayOS — All Page Components
// ─────────────────────────────────────────────────────────────────
import React, { useState, useEffect, useRef } from 'react';
import { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer, BarChart, Bar } from 'recharts';
import * as api from '../services/api';

// ══════════════════════════════════════════
//  OVERVIEW
// ══════════════════════════════════════════
export function Overview({ setScreen }) {
  const [payments, setPayments] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.listPayments({ limit: 10 })
      .then(d => setPayments(d.data || d.payments || []))
      .catch(() => setPayments(MOCK_PAYMENTS))
      .finally(() => setLoading(false));
  }, []);

  return (
    <div>
      <div className="page-header">
        <div className="page-title">Payment Intelligence Suite</div>
        <div className="page-sub">All systems operational · <span>Hyperswitch connected</span></div>
      </div>

      <div className="stats-row">
        {[
          { label: 'TOTAL VOLUME',   value: '₹4.2Cr', delta: '↑ 12.3% vs yesterday', up: true },
          { label: 'SUCCESS RATE',   value: '94.7%',  delta: '↑ 2.1% · NeuralRoute active', up: true },
          { label: 'ANOMALIES',      value: '3',      delta: '↑ 2 new in last hour', up: false, color: 'var(--orange)' },
          { label: 'RECON MATCH',    value: '98.2%',  delta: '5 mismatches pending', up: true, color: 'var(--blue)' },
        ].map((s, i) => (
          <div className="stat-card" key={i}>
            <div className="stat-label">{s.label}</div>
            <div className="stat-value" style={s.color ? { color: s.color } : {}}>{s.value}</div>
            <div className={`stat-delta ${s.up ? 'delta-up' : 'delta-down'}`}>{s.delta}</div>
          </div>
        ))}
      </div>

      <div className="modules-grid">
        {[
          { id: 'neuralroute', icon: '🔀', cls: 'icon-green',  name: 'NeuralRoute', desc: 'ML model predicts best gateway before each payment. 91% accuracy. Auto-reroutes on failure.', stat: <span>Active: <span style={{color:'var(--green)'}}>Razorpay (91% conf)</span></span> },
          { id: 'sentinel',    icon: '🛡️', cls: 'icon-purple', name: 'SentinelPay', desc: 'Isolation Forest AI detects anomalies. Auto-generates incident reports in plain English.',    stat: <span>Status: <span style={{color:'var(--orange)'}}>3 anomalies detected</span></span> },
          { id: 'flowforge',   icon: '⚡', cls: 'icon-orange', name: 'FlowForge',   desc: 'AI generates checkout UI from brand description. No-code config. 1-click embed SDK.',        stat: <span>Checkouts today: <span style={{color:'var(--orange)'}}>1,247</span></span> },
          { id: 'clearledger', icon: '📊', cls: 'icon-blue',   name: 'ClearLedger', desc: 'AI explains reconciliation mismatches. Auto-generates dispute letters.',                     stat: <span>Pending: <span style={{color:'var(--blue)'}}>₹12,340 in 5 mismatches</span></span> },
        ].map(m => (
          <div className="module-card" key={m.id} onClick={() => setScreen(m.id)}>
            <div className={`module-icon ${m.cls}`}>{m.icon}</div>
            <div className="module-name">{m.name}</div>
            <div className="module-desc">{m.desc}</div>
            <div className="module-stat">{m.stat}</div>
          </div>
        ))}
      </div>

      <div className="card">
        <div className="section-title">Recent Transactions <span className="tag tag-green">LIVE</span></div>
        {loading ? <div className="loading"><div className="spinner"/>Loading from Hyperswitch...</div> : (
          <table className="txn-table">
            <thead><tr><th>TXN ID</th><th>AMOUNT</th><th>METHOD</th><th>GATEWAY</th><th>STATUS</th><th>AI CONF</th></tr></thead>
            <tbody>
              {(payments.length ? payments : MOCK_PAYMENTS).map((p, i) => (
                <tr key={i}>
                  <td style={{fontFamily:'var(--mono)',fontSize:'0.75rem',color:'var(--muted)'}}>{p.payment_id || p.id || `pay_${i}`}</td>
                  <td style={{fontFamily:'var(--mono)',fontWeight:700}}>₹{((p.amount || 0)/100).toFixed(0)}</td>
                  <td>{p.payment_method || p.method || 'upi'}</td>
                  <td style={{color:'var(--blue)',fontFamily:'var(--mono)',fontSize:'0.78rem'}}>{p.connector || p.gateway || 'razorpay'}</td>
                  <td><span className={`status-badge status-${p.status}`}>{p.status}</span></td>
                  <td style={{fontFamily:'var(--mono)',fontSize:'0.78rem',color:'var(--green)'}}>{Math.floor(Math.random()*20+75)}%</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

// ══════════════════════════════════════════
//  PAYAGENT
// ══════════════════════════════════════════
export function PayAgent() {
  const [messages, setMessages] = useState([{
    role: 'agent',
    text: "Hi! I'm **PayAgent** — your autonomous payment AI.\n\nI can detect anomalies, reroute traffic, reconcile mismatches, and generate checkout UIs — all in one message.\n\nTry: \"What's wrong with my payments today?\"",
    time: now(),
  }]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [toolCalls, setToolCalls] = useState([]);
  const [logs, setLogs] = useState(INIT_LOGS);
  const messagesEnd = useRef(null);

  useEffect(() => { messagesEnd.current?.scrollIntoView({ behavior: 'smooth' }); }, [messages]);

  const send = async (msg) => {
    if (!msg.trim() || loading) return;
    setInput('');
    const userMsg = { role: 'user', text: msg, time: now() };
    setMessages(m => [...m, userMsg]);
    setLoading(true);

    try {
      const res = await api.chatWithAgent(msg, []);
      if (res.toolCallsMade?.length) {
        setToolCalls(res.toolCallsMade);
        res.toolCallsMade.forEach(tc => {
          setMessages(m => [...m, { role: 'tool', text: `${tc.tool}(${JSON.stringify(tc.input)})`, time: now() }]);
        });
      }
      setMessages(m => [...m, { role: 'agent', text: res.response, time: now() }]);
      setLogs(l => [{ time: now(), text: `PayAgent called ${res.toolCallsMade?.[0]?.tool || 'tools'}` }, ...l.slice(0, 9)]);
    } catch {
      setMessages(m => [...m, { role: 'agent', text: 'Demo mode: API not connected. In production, I use Claude AI with real tool calls to autonomously manage your payments.', time: now() }]);
    }
    setLoading(false);
  };

  return (
    <div>
      <div className="page-header">
        <div className="page-title">🤖 PayAgent</div>
        <div className="page-sub">AI Agent · <span>Claude API Tool Use · Autonomous payment operations</span></div>
      </div>
      <div className="agent-layout">
        {/* Chat */}
        <div className="agent-chat">
          <div className="agent-header">
            <div className="agent-avatar">🤖</div>
            <div><div style={{fontWeight:700,fontSize:'0.95rem'}}>PayAgent</div><div style={{fontSize:'0.75rem',color:'var(--muted)'}}>Powered by Claude AI · Tool Use enabled</div></div>
            <div className="badge-live" style={{marginLeft:'auto'}}>● ONLINE</div>
          </div>
          <div className="chat-messages">
            {messages.map((m, i) => (
              <div key={i} className={`msg msg-${m.role === 'user' ? 'user' : 'agent'}`}>
                {m.role === 'tool'
                  ? <div className="tool-call-bubble">{m.text}</div>
                  : <div className="msg-bubble" dangerouslySetInnerHTML={{ __html: formatMsg(m.text) }} />
                }
                <div className="msg-time">{m.time}</div>
              </div>
            ))}
            {loading && (
              <div className="msg msg-agent">
                <div className="msg-bubble"><div className="typing"><div className="typing-dot"/><div className="typing-dot"/><div className="typing-dot"/></div></div>
              </div>
            )}
            <div ref={messagesEnd}/>
          </div>
          <div className="chat-input-area">
            <div className="quick-prompts">
              {["What's wrong with my payments?","Reroute away from PayU","Explain my mismatches","Generate luxury checkout"].map(p => (
                <div key={p} className="quick-prompt" onClick={() => send(p)}>{p}</div>
              ))}
            </div>
            <div className="chat-input-row">
              <textarea className="chat-input" rows={1} value={input} onChange={e => setInput(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(input); }}}
                placeholder="Ask PayAgent anything about your payments..."/>
              <button className="btn-send" onClick={() => send(input)}>→</button>
            </div>
          </div>
        </div>

        {/* Sidebar */}
        <div style={{display:'flex',flexDirection:'column',gap:'1rem'}}>
          <div className="tools-card">
            <div className="section-title" style={{fontSize:'0.85rem',marginBottom:'0.75rem'}}>Agent Tools</div>
            {[
              {name:'check_anomalies()',desc:'SentinelPay detector'},
              {name:'route_payment()',desc:'NeuralRoute ML engine'},
              {name:'reconcile()',desc:'ClearLedger engine'},
              {name:'generate_checkout()',desc:'FlowForge AI builder'},
            ].map((t, i) => (
              <div className="tool-item" key={i}>
                <div className={`tool-dot ${toolCalls.some(tc => tc.tool === t.name.replace('()','')) ? 'tool-active' : 'tool-active'}`}/>
                <div><div className="tool-name">{t.name}</div><div className="tool-desc">{t.desc}</div></div>
              </div>
            ))}
          </div>
          <div className="activity-log-card">
            <div className="section-title" style={{fontSize:'0.85rem',marginBottom:'0.75rem'}}>Activity Log</div>
            {logs.map((l, i) => (
              <div className="log-item" key={i}>
                <div className="log-time">{l.time}</div>
                <div className="log-text" dangerouslySetInnerHTML={{__html: l.text}}/>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

// ══════════════════════════════════════════
//  NEURALROUTE
// ══════════════════════════════════════════
export function NeuralRoute() {
  const [health, setHealth] = useState(null);
  const [prediction, setPrediction] = useState(null);
  const [form, setForm] = useState({ amount: 85000, method: 'upi' });

  useEffect(() => {
    api.getGatewayHealth().then(setHealth).catch(() => setHealth(MOCK_HEALTH));
  }, []);

  const predict = () => {
    api.predictGateway(form)
