        <div className="page-sub">AI Anomaly Detection · <span>Isolation Forest · Z-Score Analysis</span></div>
      </div>

      <div className="stats-row" style={{gridTemplateColumns:'repeat(3,1fr)'}}>
        <div className="stat-card"><div className="stat-label">TOTAL SCANNED</div><div className="stat-value">{data?.summary?.scannedTxns || 200}</div><div className="stat-delta delta-up">Last 24 hours</div></div>
        <div className="stat-card"><div className="stat-label">ANOMALIES</div><div className="stat-value" style={{color:'var(--orange)'}}>{data?.summary?.totalAnomalies ?? 3}</div><div className="stat-delta delta-down">Active alerts</div></div>
        <div className="stat-card"><div className="stat-label">AUTO-RESOLVED</div><div className="stat-value" style={{color:'var(--green)'}}>1</div><div className="stat-delta delta-up">By NeuralRoute</div></div>
