      <div className="card" style={{marginBottom:'1rem'}}>
        <div className="section-title">24h Transaction Heatmap <span className="tag tag-purple">AI MONITORED</span></div>
        <div style={{display:'flex',justifyContent:'space-between',fontFamily:'var(--mono)',fontSize:'0.62rem',color:'var(--dim)',marginBottom:'6px'}}>
          {['00:00','06:00','12:00','18:00','23:00'].map(t => <span key={t}>{t}</span>)}
        </div>
        <div className="heatmap-grid">
          {(loading ? Array(24).fill({rate:0,count:0}) : heatmap).map((h, i) => {
            const level = h.rate > 0.25 ? 4 : h.rate > 0.15 ? 3 : h.rate > 0.08 ? 2 : h.rate > 0.02 ? 1 : 0;
            return <div key={i} className={`heat-cell heat-${level}`} title={`${i}:00 — ${Math.round(h.rate*100)}% failure (${h.count} txns)`}/>;
          })}
