        <div style={{display:'flex',gap:'1rem',fontSize:'0.72rem',fontFamily:'var(--mono)',color:'var(--muted)'}}>
          {[['Normal','var(--green)',0.06],['Elevated','var(--orange)',0.35],['Anomaly','var(--red)',0.75]].map(([l,c,o]) => (
            <span key={l}><span style={{display:'inline-block',width:'10px',height:'10px',background:c,opacity:o,borderRadius:'2px',marginRight:'4px'}}/>{l}</span>
          ))}
        </div>
      </div>

      <div className="section-title">AI-Generated Alerts <span className="tag tag-purple">{alerts.length || 3} ACTIVE</span></div>
      {(alerts.length ? alerts : MOCK_ALERTS).map((a, i) => (
        <div className={`alert-item ${a.severity === 'CRITICAL' ? 'critical' : 'warning'}`} key={i}>
          <div className="alert-icon">🤖</div>
          <div style={{flex:1}}>
            <div className="alert-title">{a.severity === 'CRITICAL' ? '🔴' : '🟡'} {a.type?.replace(/_/g,' ')}</div>
            <div className="alert-desc">{a.message}</div>
            {a.zScore && <div className="alert-meta">Z-Score: {a.zScore}σ · Hour: {a.hour}:00</div>}
          </div>
          <div className="alert-actions">
            <button className="btn-success-sm">Resolve</button>
            <button className="btn-outline">Details</button>
          </div>
        </div>
      ))}
    </div>
  );
}

