// ══════════════════════════════════════════
export function ClearLedger() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [letter, setLetter] = useState('');

  useEffect(() => {
    api.runReconciliation().then(setData).catch(() => setData(MOCK_RECON_DATA)).finally(() => setLoading(false));
  }, []);

  const getDispute = (mismatch) => {
    api.getDisputeLetter(mismatch).then(r => setLetter(r.letter)).catch(() => setLetter(MOCK_DISPUTE_LETTER));
  };

  if (loading) return <div className="loading"><div className="spinner"/>Running reconciliation...</div>;

  const summary    = data?.summary    || MOCK_RECON_DATA.summary;
  const mismatches = data?.mismatches || MOCK_RECON_DATA.mismatches;

  return (
    <div>
      <div className="page-header">
        <div className="page-title">📊 ClearLedger</div>
        <div className="page-sub">AI Reconciliation · <span>Auto-matches transactions · Dispute generation</span></div>
      </div>

      <div className="recon-stats">
        <div className="recon-stat"><div className="recon-value" style={{color:'var(--green)'}}>{summary.matched}</div><div className="recon-label">MATCHED</div></div>
        <div className="recon-stat"><div className="recon-value" style={{color:'var(--orange)'}}>{summary.mismatches}</div><div className="recon-label">MISMATCHES</div></div>
        <div className="recon-stat"><div className="recon-value" style={{color:'var(--red)'}}>₹{((summary.totalAtRisk||0)/100).toFixed(0)}</div><div className="recon-label">AT RISK</div></div>
      </div>

      <div className="section-title">AI-Explained Mismatches <span className="tag tag-blue">{summary.mismatches} PENDING</span></div>

      {(mismatches.length ? mismatches : MOCK_RECON_DATA.mismatches).map((m, i) => (
        <div className="mismatch-item" key={i}>
          <div className="mismatch-type" style={{background: m.type==='MISSING_SETTLEMENT'?'var(--red)':m.type==='AMOUNT_MISMATCH'?'var(--orange)':'var(--purple)'}}/>
          <div>
            <div className="mismatch-title">{m.paymentId}</div>
            <div style={{fontFamily:'var(--mono)',fontSize:'0.7rem',color:'var(--muted)'}}>{m.type?.replace(/_/g,' ')} · {m.gateway}</div>
            <div className="mismatch-ai">{m.aiExplanation || 'AI analysis pending...'}</div>
          </div>
          <div>
            <div className="mismatch-amount" style={{color:'var(--orange)'}}>₹{((m.amount||0)/100).toFixed(0)}</div>
            <button className="btn-outline" style={{marginTop:'0.5rem',width:'100%',fontSize:'0.72rem'}} onClick={() => getDispute(m)}>Dispute →</button>
          </div>
        </div>
      ))}

      {letter && (
        <div className="card" style={{marginTop:'1rem'}}>
          <div className="section-title">📄 Auto-Generated Dispute Letter</div>
          <pre style={{fontFamily:'var(--mono)',fontSize:'0.78rem',color:'var(--muted)',whiteSpace:'pre-wrap',lineHeight:1.6}}>{letter}</pre>
          <button className="btn-primary" style={{marginTop:'1rem'}} onClick={() => navigator.clipboard.writeText(letter)}>Copy Letter</button>
        </div>
      )}

      <div style={{marginTop:'1.5rem',display:'flex',gap:'0.75rem'}}>
        <button className="btn-primary">⬇ Export CSV Report</button>
        <button className="btn-outline" onClick={() => api.runReconciliation().then(setData).catch(() => setData(MOCK_RECON_DATA))}>↻ Re-run Reconciliation</button>
      </div>
    </div>
  );
}

